    if len(arr) <= 1:
        return arr

    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])

    return merge(left, right)

def merge(left, right):
    result = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] < right[j]:
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1
    result.extend(left[i:])
    result.extend(right[j:])
    return result

Алгоритм Дейкстры:
queue = [(0, start)]
distances = {node: float('inf') for node in graph}
distances[start] = 0

while queue:
    current_distance, current_node = heapq.heappop(queue)

    if current_distance > distances[current_node]:
        continue

    for neighbor, weight in graph[current_node]:
        distance = current_distance + weight
        if distance < distances[neighbor]:
            distances[neighbor] = distance
            heapq.heappush(queue, (distance, neighbor))

return distances

Алгоритм Рабина-Карпа:
base, mod = 256, 101
n, m = len(text), len(pattern)
hash_text, hash_pattern = 0, 0
h = 1

for i in range(m - 1):
    h = (h * base) % mod

for i in range(m):
    hash_pattern = (base * hash_pattern + ord(pattern[i])) % mod
    hash_text = (base * hash_text + ord(text[i])) % mod

for i in range(n - m + 1):
    if hash_pattern == hash_text and text[i:i+m] == pattern:
        return i
    if i < n - m:
        hash_text = (base * (hash_text - ord(text[i]) * h) + ord(text[i + m])) % mod
        if hash_text < 0:
            hash_text += mod

return -1
